// The kit's icons, as path data. Exported from the Graphite UI Kit's three
// straight-corner icon pages (Icons (Regular) fi-rs, Icons (Bold) fi-bs, Icons
// (Solid) fi-ss), every glyph on a 16 × 16 grid, coordinates rounded to two
// decimals. Only the icons the site draws are here; add one by exporting the
// same name from all three pages.
//
// The kit's glyphs are Flaticon's UIcons, used under the Flaticon licence,
// which asks for a credit: see the site footer.
//
// Solid has no check and no exclamation (a stroke has nothing to fill), so
// Solid borrows Bold's for those two. Its arrows, angles, plus, minus, dots and
// spinner are identical to Regular's in the kit, for the same reason. Delete
// (Menu's destructive row) is drawn on the Regular page only, so Bold and
// Solid borrow Regular's. So do Data table's sort glyphs (apps-sort and the
// two small arrows), which the kit also draws on the Regular page only, and
// Date picker's calendar, Password input's eye and eye-crossed, and Number
// input's plus-small and minus-small, which the Bold and Solid pages do not
// carry, and Tree view's caret-right, caret-down, folder and document, which
// the Bold and Solid pages do not carry either.

export const ICON_SETS = ['regular', 'bold', 'solid'] as const
export type IconSet = (typeof ICON_SETS)[number]

export type KitIconName =
  | 'copy' | 'exclamation' | 'trash' | 'share' | 'shopping-bag' | 'menu-dots'
  | 'spinner' | 'plus' | 'minus' | 'arrow-left' | 'arrow-right' | 'check'
  | 'angle-small-down' | 'angle-small-right' | 'search' | 'settings' | 'info'
  | 'user' | 'cloud-upload' | 'database' | 'bread-slice' | 'cross-small'
  | 'delete' | 'apps-sort' | 'arrow-small-up' | 'arrow-small-down' | 'calendar'
  | 'eye' | 'eye-crossed' | 'plus-small' | 'minus-small' | 'caret-right'
  | 'caret-down' | 'folder' | 'document'
  | 'moon' | 'sun' | 'menu-burger' | 'gem' | 'layout-fluid' | 'fill' | 'dice'
  | 'redo-alt' | 'refresh' | 'download' | 'copy-alt' | 'angle-small-up'
  | 'time-past'

type Paths = Record<KitIconName, string[]>

